input.command:
cd ~/DEV/_INBOX && python3 -I - <<'EOF' > $CLAUDE_JOB_DIR/tmp/perfolder.txt; cat $CLAUDE_JOB_DIR/tmp/perfolder.txt
import csv, sqlite3
from collections import defaultdict
P="00_Primary_Storage_Drive/"
def key(path):
    rest = path[len(P):].split("/")
    if rest[0]=="10_ARCHIVE": return "/".join(rest[:3] if rest[2]!="OneDrive-Import" else rest[:6])
    return "/".join(rest[:2])
cand = defaultdict(lambda:[0,0])
for r in csv.DictReader(open("drive-index/delete_candidates.csv")):
    k=key(r["path"]); cand[k][0]+=1; cand[k][1]+=int(r["size"])
tot = defaultdict(lambda:[0,0])
con=sqlite3.connect("drive-index/drive.sqlite")
for folder,name,size in con.execute("select folder,name,size from files where zone in ('parked','unsorted') and mime!='application/vnd.google-apps.folder'"):
    k=key(f"{folder}/{name}"); tot[k][0]+=1; tot[k][1]+=size
print("| folder | files | twin kept | % | size of twins |\n|---|---|---|---|---|")
for k,(n,b) in sorted(tot.items(), key=lambda x:-x[1][1]):
    c=cand[k]
    if n>=20: print(f"| `{k.replace('10_ARCHIVE/_PARKED_COPIES','_PARKED').replace('OneDrive-Import/00_Primary_Storage_Drive','OneDrive-Import')}` | {n:,} | {c[0]:,} | {100*c[0]//n}% | {c[1]/2**30:.1f} GB |")
EOF

