def selftest():
    names = {"P": PRIMARY, "R": "03_REPORTS", "X": "_PARKED_COPIES", "A": "10_ARCHIVE", "L": "loop"}
    parents = {"f1": "R", "R": "P", "P": "root", "f2": "X", "X": "A", "A": "P", "f3": "L", "L": "L",
               "f4": "shared"}
    assert resolve(parents, names, "root", "f1") == f"{PRIMARY}/03_REPORTS"
    assert zone(resolve(parents, names, "root", "f2")) == "parked"
    assert resolve(parents, names, "root", "f3") is None                 # cycle guard
    assert resolve(parents, names, "root", "f4") is None                 # parent not owned
