import csv, json, sqlite3, subprocess, sys, threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

OUT = Path.home() / "DEV/_INBOX/drive-index"
REVIEW_ID = "1Hx7wGpZZ2hFLdybZ73UWBC9UGEaGZo8-"
LIVE = ("ladder", "reports", "archive", "personal", "pipeline", "primary_other", "root_other")
EMPTY_MD5 = "d41d8cd98f00b204e9800998ecf8427e"
LOG = OUT / "trash_log_2026-10-22.csv"


def gws(args):
    for _ in range(3):
        r = subprocess.run(["gws", "drive", "files", *args], capture_output=True, text=True)
        try:
            return json.loads(r.stdout)
        except ValueError:
            continue
    return None


def get(fid):
    return gws(["get", "--params", json.dumps(
        {"fileId": fid, "fields": "id,md5Checksum,size,trashed,parents"})])


def same(meta, md5, size):
    return (meta and not meta.get("trashed") and int(meta.get("size", -1)) == size
            and meta.get("md5Checksum") == md5)


con = sqlite3.connect(OUT / "drive.sqlite")
cands = con.execute("select id, md5, size from files where zone='review' and md5 is not null").fetchall()
twins = {}
for md5, fid in con.execute(f"select md5, id from files where md5 is not null and size>0 and zone in {LIVE}"):
    twins.setdefault(md5, []).append(fid)
work = [(fid, md5, size) for fid, md5, size in cands if size == 0 or md5 in twins]
limit = int(sys.argv[sys.argv.index("--limit") + 1]) if "--limit" in sys.argv else len(work)
work = work[:limit]
print(f"candidates: {len(work)} (of {len(cands)} in _TO_REVIEW)", flush=True)

lock, done = threading.Lock(), set()
if LOG.exists():
    done = {r[0] for r in csv.reader(open(LOG)) if r[1] == "trashed"}
log = open(LOG, "a", newline="")
w = csv.writer(log)
counts = {}


def one(item):
    fid, md5, size = item
    if fid in done:
        return "already"
    c = get(fid)
    if not same(c, md5, size) or REVIEW_ID not in (c.get("parents") or []):
        status, twin = "skip_changed", ""
    else:
        twin = ""
        if size == 0:
            ok = md5 == EMPTY_MD5
        else:
            ok = False
            for t in twins[md5][:3]:
                if same(get(t), md5, size):
                    ok, twin = True, t
                    break
        if not ok:
            status = "skip_no_live_twin"
        else:
            r = gws(["update", "--params", json.dumps({"fileId": fid, "fields": "id,trashed"}),
