import sqlite3, collections, csv
con = sqlite3.connect("drive.sqlite")
LIVE = ('ladder','reports','archive','personal','pipeline','primary_other','root_other')
live = {(m,s) for m,s in con.execute(f"select md5,size from files where md5 is not null and size>0 and zone in {LIVE}")}
trashed = {r[0] for r in csv.reader(open("trash_log_2026-10-22.csv")) if r[1]=="trashed"}
depth = {'parked':5,'unsorted':4,'computers':3,'review':2}
g = collections.defaultdict(lambda:[0,0,0,0,0])  # files, bytes, twins, twinbytes, nomd5(gdocs)
for fid,zone,folder,size,md5 in con.execute("select id,zone,folder,size,md5 from files where zone in ('parked','unsorted','computers','review')"):
    if fid in trashed: continue
    key = (zone, "/".join(folder.split("/")[:depth[zone]]))
    r = g[key]; r[0]+=1; r[1]+=size or 0
